<?php
 namespace QQWorld\ConfigurableProduct\Model; class ProductVariationsBuilder { private $customAttributeFactory; protected $productFactory; private $variationMatrix; public function __construct( \QQWorld\Catalog\Model\ProductFactory $productFactory, \QQWorld\Framework\Api\AttributeValueFactory $customAttributeFactory, \QQWorld\ConfigurableProduct\Model\Product\Type\VariationMatrix $variationMatrix ) { $this->productFactory = $productFactory; $this->customAttributeFactory = $customAttributeFactory; $this->variationMatrix = $variationMatrix; } public function create(\QQWorld\Catalog\Api\Data\ProductInterface $product, $attributes) { $variations = $this->variationMatrix->getVariations($attributes); $products = []; foreach ($variations as $variation) { $price = $product->getPrice(); $item = $this->productFactory->create(); $item->setData($product->getData()); $suffix = ''; foreach ($variation as $attributeId => $valueInfo) { $suffix .= '-' . $valueInfo['value']; $customAttribute = $this->customAttributeFactory->create() ->setAttributeCode($attributes[$attributeId]['attribute_code']) ->setValue($valueInfo['value']); $customAttributes = array_merge( $item->getCustomAttributes(), [ $attributes[$attributeId]['attribute_code'] => $customAttribute ] ); $item->setData('custom_attributes', $customAttributes); } $item->setPrice($price); $item->setName($product->getName() . $suffix); $item->setSku($product->getSku() . $suffix); $item->setVisibility(\QQWorld\Catalog\Model\Product\Visibility::VISIBILITY_NOT_VISIBLE); $products[] = $item; } return $products; } } 